import{z as A,x as B,o as E,c as p,q as n,j as i,D as l,d as e,s as t,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"外核与库 OS","description":"","frontmatter":{"title":"外核与库 OS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exokernel-libos.md","filePath":"cs/exokernel-libos.md","lastUpdated":1791063341000}'),d={name:"cs/exokernel-libos.md"};function c(m,a,u,h,S,D){const s=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="外核与库-os" tabindex="-1">外核与库 OS <a class="header-anchor" href="#外核与库-os" aria-label="Permalink to &quot;外核与库 OS&quot;">​</a></h1><div class="epigraph"><p>外核只安全地复用硬件：把页、块、网卡队列的能力交给库 OS，抽象（文件、进程）在用户库里实现，避免内核强加错误抽象。</p><footer>—— 据 Engler, Kaashoek, O&#39;Toole, Exokernel, SOSP 1995；[unikernel](/cs/unikernel) 为库 OS 部署形态</footer></div><p><a href="/cs/microkernel-sel4">seL4</a> 仍提供页与 IPC 抽象。外核更狠：<strong>几乎不提供 POSIX</strong>。缺口是 Exokernel 直觉，以及和 DPDK 的亲缘。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宏内核的文件可能不是应用要的。外核：分配物理页、时间片、磁盘块号给库，库自己实现 FS。缺口：安全复用（撤销能力）；多应用如何共存。本课不把 1995 年实验当今日默认。<span class="marginnote">术语翻译：外核就是用「内核只把硬件资源安全地分下去、并且随时收得回来」的手段来做「把抽象的选择权交还给应用」的事——内核不再是管家，而是地契登记处。</span></p><p><span class="marginnote">DPDK/VFIO 是外核精神在 Linux 上的局部实现：把网卡交给库。对象是抽象下沉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核：保护 + 调度原始资源。libOS：TCP、文件。对照 <a href="/cs/paravirtualization">virtio</a>：客户库对环。对照 <a href="/cs/malloc-implementation">malloc</a>：用户已在切页。对照 Kata：相反，再加一层通用 OS。</p>',8)),(E(),i(o,null,{default:l(()=>[t(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HW%5B%22%E7%A1%AC%E4%BB%B6%E8%B5%84%E6%BA%90%22%5D%20--%3E%20EXO%5B%22%E5%A4%96%E6%A0%B8%E5%AE%89%E5%85%A8%E5%A4%8D%E7%94%A8%22%5D%0A%20%20EXO%20--%3E%20LIB%5B%22%E5%BA%93%20OS%20%E5%AE%9E%E7%8E%B0%E6%8A%BD%E8%B1%A1%22%5D%0A%20%20LIB%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("外核把「内核该提供什么」从 POSIX 改成安全复用，让应用选抽象。今日以旁路 I/O 和 unikernel 复活。不要写成取消操作系统。与 "),r("a",{href:"/cs/memcg"},"memcg"),e("：仍要有人做会计，或完全静态划分。")],-1)),(E(),i(o,null,{default:l(()=>[t(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20M%5B%22%E5%AE%8F%E5%86%85%E6%A0%B8%E6%A0%88%22%5D%0A%20%20%20%20A1%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20K1%5B%22%E5%86%85%E6%A0%B8%EF%BC%9A%E6%96%87%E4%BB%B6%20%2B%20TCP%20%2B%20%E8%B0%83%E5%BA%A6%E4%B8%80%E8%B5%B7%E5%8C%85%E5%8A%9E%22%5D%20--%3E%20H1%5B%22%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20end%0A%20%20subgraph%20X%5B%22%E5%A4%96%E6%A0%B8%E6%A0%88%22%5D%0A%20%20%20%20A2%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20L2%5B%22%E5%BA%93%20OS%EF%BC%9A%E5%BA%94%E7%94%A8%E8%87%AA%E5%B7%B1%E5%AE%9E%E7%8E%B0%E6%96%87%E4%BB%B6%E4%B8%8E%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20E2%5B%22%E5%A4%96%E6%A0%B8%EF%BC%9A%E5%8F%AA%E7%AE%A1%E5%88%86%E9%85%8D%E4%B8%8E%E5%BC%BA%E5%88%B6%E5%9B%9E%E6%94%B6%22%5D%20--%3E%20H2%5B%22%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20end%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">直觉类比：宏内核像配家具的公寓房东，租客只能用现成的家具（固定文件系统、协议栈）；外核像只卖地皮的开发商——保证地契（资源所有权）可执行，房子（抽象）你想怎么盖就怎么盖。</span></p><p>无通用抽象则工具链断裂。</p><p>实现上：撤销能力必须能收回已借出的帧和时间片。今日 DPDK/SPDK 是同一精神的局部。没有通用文件抽象则备份与安全工具都要按应用重做。 读法上只引用<a href="/cs/microkernel-sel4">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>外核与库 OS</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 Aegis/ExOS 细节。不保证多租安全证明等于 seL4。下一课语言：Rust in kernel。<span class="marginnote">常见误区：初学者容易以为「外核 = 没有操作系统」；实际上时间片、物理页的强制回收仍由内核执行，安全边界一点没少，被搬走的只是文件、进程这些「怎么用」的抽象。</span></p><p>版本字段会变，课序钉的是机制对象「外核与库 OS」，不是某一主线内核的结构体名。 后课默认：抽象可放在库里，内核只保复用。用 Rust 写内核模块，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外核：安全复用原始硬件；库 OS 做文件/协议。</li><li>与今日用户态驱动/unikernel 同谱。</li><li>Rust in kernel 是下一课。</li><li>出处：Engler et al., SOSP 1995；L4/unikernel 对照。</li></ul>',10))])}const P=A(d,[["render",c]]);export{f as __pageData,P as default};
